t.script:
{"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [
{"@type": "Question", "name": "Do you stock bearings locally in El Paso?", "acceptedAnswer": {"@type": "Answer", "text": "Yes. We hold bearings at our El Paso stocking location at 3950 Doniphan Dr Ste P and can pull from our supplier network for anything not on the shelf. Call 915-845-8188 and we will confirm availability the same day."}},
{"@type": "Question", "name": "Can you cross-reference a bearing part number I already have?", "acceptedAnswer": {"@type": "Answer", "text": "Yes, and it is most of what we do. Send the number stamped on the bearing, or the dimensions you measured, and our engineers will match it across every brand we carry. If the number is unreadable, bore, outside diameter and width are enough to identify it."}},
{"@type": "Question", "name": "Do you deliver bearings into Juárez?", "acceptedAnswer": {"@type": "Answer", "text": "Yes. We support the Juárez maquiladora corridor with same-day cross-border supply from our El Paso location."}},
{"@type": "Question", "name": "What is the difference between 2RS and ZZ bearings?", "acceptedAnswer": {"@type": "Answer", "text": "2RS means a rubber seal on both sides, contacting the rotating ring. ZZ means a metal shield on both sides, non-contacting. Choose 2RS for moisture and fine contamination, ZZ for dust and higher speed with lower friction."}},
{"@type": "Question", "name": "Which bearing clearance should I specify?", "acceptedAnswer": {"@type": "Answer", "text": "Normal clearance suits most applications. Specify C3 where the bearing runs hot from the fit or from thermal expansion in service, which is why C3 is common in electric motors and pumps. C2 is for precision work where runout must stay tight."}}
]}
